theorem H_hat_conj_sigma (hα : 1 < α) (ρ σ : MState d) :
    let γ := (1 - α) / (2 * α)
    (H_hat α ρ σ).conj (σ.M ^ (-γ)).mat = (ρ.M.conj (σ.M ^ γ).mat) ^ (α - 1)

lemma inner_rho_H_hat (hα : 1 < α) (ρ σ : MState d) :
    let γ := (1 - α) / (2 * α)
    ⟪ρ.M, H_hat α ρ σ⟫_ℝ = ((ρ.M.conj (σ.M ^ γ).mat) ^ α).trace

lemma rpow_mul_neg_rpow_eq_supportProj {A : HermitianMat d ℂ}
    (hA : 0 ≤ A) (γ : ℝ) (hγ : γ ≠ 0) :
    (A ^ γ).mat * (A ^ (-γ)).mat = A.supportProj.mat

lemma supportProj_mul_of_ker_le {A B : HermitianMat d ℂ}
    (hker : A.ker ≤ B.ker) :
    A.supportProj.mat * B.mat = B.mat

theorem ker_le_traceRight {ρ σ : MState (dA × dB)}
    (hker : σ.M.ker ≤ ρ.M.ker) :
    σ.traceRight.M.ker ≤ ρ.traceRight.M.ker

lemma HermitianMat.mul_supportProj_of_ker_le {A B : HermitianMat d ℂ}
  (h : LinearMap.ker B.lin.toLinearMap ≤ LinearMap.ker A.lin.toLinearMap) :
    A.mat * B.supportProj.mat = A.mat

lemma HermitianMat.inner_supportProj_of_ker_le {A B : HermitianMat d ℂ}
  (h : LinearMap.ker B.lin.toLinearMap ≤ LinearMap.ker A.lin.toLinearMap) :
    ⟪A, B.supportProj⟫ = A.trace

lemma sandwichedRelRentropy_nonneg {α : ℝ} (hα : 0 < α) (h : σ.M.ker ≤ ρ.M.ker) :
    0 ≤ if α = 1 then ⟪ρ.M, ρ.M.log - σ.M.log⟫
      else ((ρ.M.conj (σ.M ^ ((1 - α)/(2 * α)) ).mat) ^ α).trace.log / (α - 1)

lemma qRelativeEnt_eq_neg_Sᵥₙ_add (ρ σ : MState d) :
    (qRelativeEnt ρ σ).toEReal = -(Sᵥₙ ρ : EReal) +
      if σ.M.ker ≤ ρ.M.ker then (-⟪ρ.M, σ.M.log⟫ : EReal) else (⊤ : EReal)

theorem Sᵥₙ_strong_subadditivity (ρ₁₂₃ : MState (d₁ × d₂ × d₃)) :
    let ρ₁₂ := ρ₁₂₃.assoc'.traceRight;
    let ρ₂₃ := ρ₁₂₃.traceLeft;
    let ρ₂ := ρ₁₂₃.traceLeft.traceRight;
    Sᵥₙ ρ₁₂₃ + Sᵥₙ ρ₂ ≤ Sᵥₙ ρ₁₂ + Sᵥₙ ρ₂₃
